import socket,sys,time,json
import arena

def think(b,seconds=60):
 s=socket.socket(socket.AF_UNIX); s.connect('/run/match/opponent-stockfish.sock');f=s.makefile()
 def send(cmd):s.sendall((cmd+'\n').encode())
 send('uci')
 for l in f:
  if l.strip()=='uciok':break
 send('setoption name Threads value 2');send('setoption name Hash value 256')
 send('isready')
 for l in f:
  if l.strip()=='readyok':break
 send('position startpos moves '+' '.join(m.uci() for m in b.move_stack))
 send(f'go movetime {int(seconds*1000)}')
 last=''
 for l in f:
  if l.startswith('info depth'):
   last=l.strip()
   if ' pv ' in l:
    depth=int(l.split()[2])
    if depth>=20: print(l.strip(),flush=True)
  if l.startswith('bestmove'):
   print(l.strip(),flush=True);best=l.split()[1];break
 send('quit');s.close()
 return best,last
if __name__=='__main__':
 if len(sys.argv)>2:arena.cmd_move(sys.argv[2])
 b=arena.load_board()
 if arena.result(b) is None:
  best,info=think(b,float(sys.argv[1]) if len(sys.argv)>1 else 60)
  open('/workdir/analysis.json','w').write(json.dumps({'best':best,'info':info,'fen':b.fen()}))
